#include <stdio.h>

int main(void) {
    int count = 3;              // a whole number; may be negative
    unsigned int pages = 250;   // a whole number that is never negative
    double price = 19.99;       // a number with a fractional part
    char grade = 'A';           // one character, written in single quotes
    size_t length = 12;         // an unsigned type for sizes and counts

    count = count + 1;          // assignment: replace the old value

    printf("count  = %d\n", count);
    printf("pages  = %u\n", pages);
    printf("price  = %f\n", price);
    printf("grade  = %c\n", grade);
    printf("length = %zu\n", length);
    return 0;
}

