#include <stdio.h>

int main(void) {
    int a = 7;
    int b = 2;
    printf("a / b   = %d\n", a / b);     // int / int: fraction thrown away
    printf("a mod b = %d\n", a % b);     // remainder
    printf("-7 / 2  = %d\n", -7 / 2);    // rounds toward zero
    printf("-7 mod 2 = %d\n", -7 % 2);   // remainder has the sign of -7
    printf("7.0 / 2 = %f\n", 7.0 / 2);   // one double: double division
    return 0;
}

#include <stdio.h>

int main(void) {
    int total = 9;
    int n = 4;
    double wrong = total / n;            // 9 / 4 is the int 2, then 2 becomes 2.0
    double right = (double) total / n;   // 9.0 / 4 is 2.25
    double late = (double) (total / n);  // cast happens after int division: 2.0
    int whole = 3.99;                    // double to int: the fraction is dropped
    printf("wrong = %f\n", wrong);
    printf("right = %f\n", right);
    printf("late  = %f\n", late);
    printf("whole = %d\n", whole);
    return 0;
}

