#include <stdio.h>

int main(void) {
    int n = 42;
    double third = 1.0 / 3.0;
    printf("[%d]\n", n);
    printf("[%5d]\n", n);         // width 5: at least 5 characters
    printf("[%-5d]\n", n);        // minus sign: left-aligned
    printf("[%1d]\n", 12345);     // too narrow: never cut off
    printf("[%.3f]\n", third);    // precision 3: 3 digits after the point
    printf("[%8.2f]\n", third);   // width 8, precision 2
    printf("[%24.17f]\n", third); // width 24, precision 17
    printf("[%.2f]\n", 2.999);    // rounded, not chopped
    printf("[%.0f]\n", 7.5);      // no digits after the point
    return 0;
}

