#include <stdio.h>

int main(void) {
    int left = 3;
    while (left > 0) {
        printf("left = %d\n", left);
        left--;                       // same as left = left - 1
    }

    for (int i = 0; i < 3; i++) {
        printf("i = %d\n", i);
    }

    int power = 1;
    for (int k = 1; k <= 5; k++) {
        power *= 2;                   // same as power = power * 2
    }
    printf("2 to the 5 = %d\n", power);
    return 0;
}

