#include <stdio.h>

// returns the square of x
int square(int x) {
    return x * x;
}

// returns the area of a w-by-h rectangle
double area(double w, double h) {
    return w * h;
}

// prints n stars and a newline; returns nothing
void stars(int n) {
    for (int i = 0; i < n; i++) {
        printf("*");
    }
    printf("\n");
}

int main(void) {
    int s = square(6);
    printf("square(6) = %d\n", s);
    printf("square(2 + 1) = %d\n", square(2 + 1));
    printf("area = %.1f\n", area(2.5, 4.0));
    stars(5);
    return 0;
}

