#include <stdio.h>

// returns 1 if year is a leap year, 0 otherwise
int is_leap(int year) {
    if (year % 400 == 0) {
        return 1;
    } else if (year % 100 == 0) {
        return 0;
    } else if (year % 4 == 0) {
        return 1;
    }
    return 0;
}

int main(void) {
    for (int y = 1896; y <= 1912; y++) {
        if (is_leap(y)) {
            printf("%d\n", y);
        }
    }
    return 0;
}
